insert into questoes (id,fonte_id,numero,disciplina_id,enunciado,texto_apoio,alternativas,gabarito,status_gabarito,revisar) values
('pmce-2021-q001','pmce-2021',1,'lingua-portuguesa','“Se não houver frutos, valeu a beleza das flores; se não houver flores, valeu a sombra das folhas; se não houver folhas, valeu a intenção da semente.” Henfil, cartunista. Sobre a estruturação desse pensamento, assinale a afirmativa correta.',null,'[{"letter":"A","text":"Os termos frutos, flores, folhas, semente indicam uma progressão de lugar e tempo."},{"letter":"B","text":"As três frases que compõem o pensamento apresentam paralelismo sintático, ou seja, mostram estruturação sintática idêntica."},{"letter":"C","text":"Cada uma das frases que compõem o pensamento de Henfil apresenta uma retificação da frase anterior."},{"letter":"D","text":"As formas verbais das frases componentes desse pensamento indicam uma ação futura."},{"letter":"E","text":"Os termos beleza, sombra e intenção indicam aspectos negativos da ação da natureza."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q002','pmce-2021',2,'lingua-portuguesa','Avalie a frase a seguir. “Os fumantes são suicidas homeopáticos.” Isso significa que os fumantes',null,'[{"letter":"A","text":"não acreditam na medicina tradicional."},{"letter":"B","text":"preferem deixar de fumar a morrer."},{"letter":"C","text":"matam-se pouco a pouco."},{"letter":"D","text":"perdem a vida sem uma razão convincente."},{"letter":"E","text":"ingerem remédios prejudiciais à saúde."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q003','pmce-2021',3,'lingua-portuguesa','“A imaginação muitas vezes nos conduz a mundos a que nunca fomos, mas sem ela não iremos a nenhum lugar.” Carl Sagan. Nessa frase podemos fazer substituições de termos ou expressões sem que se altere o significado pretendido. Assinale a opção em que a alteração proposta modifica o sentido original.',null,'[{"letter":"A","text":"“muitas vezes” = frequentemente."},{"letter":"B","text":"“nos conduz a” = nos transporta para."},{"letter":"C","text":"“a mundos” = a lugares."},{"letter":"D","text":"“mas” = logo."},{"letter":"E","text":"“a nenhum lugar” = a lugar algum."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q004','pmce-2021',4,'lingua-portuguesa','Todas as frases a seguir começam por uma metáfora. Assinale a opção que apresenta a frase em que essa metáfora inicial é explicada.',null,'[{"letter":"A","text":"A loteria é um imposto para os que são ruins em Matemática."},{"letter":"B","text":"A humanidade é a imortalidade dos mortais."},{"letter":"C","text":"A modernidade é a tensão entre o efêmero e o eterno."},{"letter":"D","text":"A vida é uma tragédia: o ato final é a morte."},{"letter":"E","text":"Os homens tornaram-se ferramentas de suas ferramentas."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q005','pmce-2021',5,'lingua-portuguesa','Analise o seguinte texto humorístico: “Larguei a bebida. O ruim é que não lembro onde.” Nesse texto, o humor é provocado',null,'[{"letter":"A","text":"pelo fato de a segunda frase dar um novo sentido ao verbo “largar”."},{"letter":"B","text":"pela situação incômoda de procurar algo sem saber onde."},{"letter":"C","text":"pela decisão anunciada na primeira frase não ter sido bem- sucedida."},{"letter":"D","text":"pelos erros gramaticais cometidos nas duas frases."},{"letter":"E","text":"pela circunstância do esquecimento provocado pela bebida."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q006','pmce-2021',6,'lingua-portuguesa','“Eu amarei a luz porque ela me mostra o caminho. Contudo, eu suportarei a escuridão, pois ela me mostra as estrelas.” Assinale a opção que indica a mensagem contida nessa frase.',null,'[{"letter":"A","text":"Todas as coisas criadas têm a finalidade de dar prazer ao homem."},{"letter":"B","text":"A natureza ensina os homens a viver de forma positiva."},{"letter":"C","text":"Os aspectos negativos da existência levam à depressão."},{"letter":"D","text":"Cada momento de nossas vidas traz aspectos positivos e negativos."},{"letter":"E","text":"O lado positivo das coisas deve ser procurado por todos."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q007','pmce-2021',7,'lingua-portuguesa','Leia a introdução de um pequeno conto de Carlos Drummond de Andrade: “O índio, informado de que aquela era a Semana do Índio, esperava na oca a chegada de visitantes, que certamente iriam cumprimentá-lo e levar-lhe algumas utilidades como presente. Chegou foi um homem de papel na mão, convidando-o a mudarse com presteza, pois a terra fora adquirida por uma empresa de reflorestamento. ” Nas narrativas, como essa, aparece sempre uma situação inicial de harmonia, que é perturbada por uma desarmonia, que é o miolo da narrativa. A desarmonia neste caso é o fato de',null,'[{"letter":"A","text":"a Semana do Índio não ser comemorada dignamente."},{"letter":"B","text":"a chegada de um homem convidando o índio a mudar-se."},{"letter":"C","text":"os visitantes não trazerem objetos de presente."},{"letter":"D","text":"o índio não ter recebido cumprimentos dos visitantes."},{"letter":"E","text":"a terra do índio ter sido adquirida por uma empresa."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q008','pmce-2021',8,'lingua-portuguesa','As frases a seguir estruturam-se a partir de uma comparação, à exceção de uma. Assinale-a.',null,'[{"letter":"A","text":"Sonhos são como deuses: quando não se acredita neles, deixam de existir."},{"letter":"B","text":"Um acontecimento vivido é finito. Um acontecimento lembrado é ilimitado."},{"letter":"C","text":"O sonho é o domingo do pensamento."},{"letter":"D","text":"Pense como homem de ação e aja como homem de pensamento."},{"letter":"E","text":"Fantasia não é exatamente uma fuga da realidade. É um modo de entendê-la."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q009','pmce-2021',9,'lingua-portuguesa','“Se não houver frutos, valeu a beleza das flores; se não houver flores, valeu a sombra das folhas; se não houver folhas, valeu a intenção da semente.” Henfil, cartunista. O que essa frase nos ensina é que',null,'[{"letter":"A","text":"a natureza nos ensina a viver melhor."},{"letter":"B","text":"o otimismo deve guiar os nossos passos."},{"letter":"C","text":"as atitudes positivas devem pautar nossos julgamentos."},{"letter":"D","text":"a desistência diante da vida é algo inevitável."},{"letter":"E","text":"as intenções das ações é que as justificam."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q010','pmce-2021',10,'lingua-portuguesa','Um texto argumentativo apresenta sempre uma tese defendida por argumentos adequados ao convencimento do leitor. Assinale a opção que indica a frase que mostra um argumento apoiado na intimidação pela vergonha.',null,'[{"letter":"A","text":"Vacine-se! A ciência recomenda!"},{"letter":"B","text":"Toda a população do Reino Unido já se vacinou. Vacine-se também!"},{"letter":"C","text":"Vacine-se ou a Covid vai pegar você!"},{"letter":"D","text":"Todas as pessoas inteligentes se vacinaram. E você?"},{"letter":"E","text":"Vacine-se! É rápido e eficiente!"}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q011','pmce-2021',11,'raciocinio-logico','Um fazendeiro plantou ao longo de uma das margens da estrada reta, que vai do portão de sua fazenda até a sua casa, vários coqueiros. Os coqueiros foram plantados em grupos de 6 coqueiros igualmente espaçados. A distância do portão ao primeiro coqueiro é de 10 metros e a distância entre o sexto coqueiro de um grupo e o primeiro coqueiro do grupo seguinte é o dobro da distância entre coqueiros consecutivos de um mesmo grupo. A distância do portão da fazenda ao quarto coqueiro é de 28 metros. A distância do terceiro ao décimo coqueiro, em metros, é',null,'[{"letter":"A","text":"48."},{"letter":"B","text":"49."},{"letter":"C","text":"54."},{"letter":"D","text":"56."},{"letter":"E","text":"60."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q012','pmce-2021',12,'raciocinio-logico','Em um grupo de 218 soldados, 147 são do sexo masculino e 71 do sexo feminino. Para um treinamento, esses 218 soldados são agrupados, aleatoriamente, formando 109 pares de soldados. Sabe-se que, exatamente, 21 pares têm dois soldados do sexo feminino. O número de pares de soldados que têm dois soldados do sexo masculino é',null,'[{"letter":"A","text":"61."},{"letter":"B","text":"59."},{"letter":"C","text":"57."},{"letter":"D","text":"55."},{"letter":"E","text":"53."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q013','pmce-2021',13,'raciocinio-logico','Em uma tabela 4 x 3, isto é, com 4 linhas e 3 colunas, a soma dos elementos de cada uma das 4 linhas é sempre a mesma. A soma dos elementos de cada uma das 3 colunas também é sempre a mesma, mas não necessariamente igual à soma dos elementos de cada linha. Sabe-se que a soma dos elementos da primeira coluna com os elementos da primeira linha é igual a 35 e que a diferença entre a soma dos elementos da terceira coluna e a soma dos elementos da segunda linha é igual a 5. A soma de todos os elementos dessa tabela é',null,'[{"letter":"A","text":"84."},{"letter":"B","text":"75."},{"letter":"C","text":"72."},{"letter":"D","text":"60."},{"letter":"E","text":"48."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q014','pmce-2021',14,'raciocinio-logico','Uma urna A contém 20 bolas vermelhas e uma urna B contém 21 bolas azuis. Essas são as únicas bolas nas duas urnas. Transferem-se, aleatoriamente, 5 bolas da urna A para a urna B. A seguir, também aleatoriamente, transferem-se 6 bolas da urna B para a urna A. É correto concluir que, ao final,',null,'[{"letter":"A","text":"há exatamente uma bola azul na urna A."},{"letter":"B","text":"há exatamente 15 bolas azuis na urna B."},{"letter":"C","text":"não há bolas vermelhas na urna B."},{"letter":"D","text":"há, no mínimo, uma bola vermelha na urna B."},{"letter":"E","text":"há, no máximo, 6 bolas azuis na urna A."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q015','pmce-2021',15,'raciocinio-logico','O soldado Ryan e sua irmã Rayane possuem, respectivamente, R$ 1172,35 e R$ 1732,75. Para que os dois fiquem com, exatamente, a mesma quantia, Rayane deve dar a Ryan',null,'[{"letter":"A","text":"R$ 1452,55."},{"letter":"B","text":"R$ 560,40."},{"letter":"C","text":"R$ 540,60."},{"letter":"D","text":"R$ 452,55."},{"letter":"E","text":"R$ 280,20."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q016','pmce-2021',16,'raciocinio-logico','O sargento Garcia tem, sob seu comando, entre 100 e 200 soldados. O sargento Garcia observou que, formando os seus soldados em filas de 14 soldados cada uma ou em filas de 18 soldados cada uma, a formação fica perfeita, isto é, não sobra nem falta soldado em qualquer fila. Quando o sargento Garcia forma os seus soldados em filas de 14 soldados cada uma, o número de filas é',null,'[{"letter":"A","text":"8."},{"letter":"B","text":"9."},{"letter":"C","text":"10."},{"letter":"D","text":"11."},{"letter":"E","text":"12."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q017','pmce-2021',17,'raciocinio-logico','Em uma prova de natação, os tempos costumam ser apresentados no formato 1:23.45, indicando, nesse caso, um tempo de 1 minuto, 23 segundos e 45 centésimos de segundo. Em uma prova de natação de 400 metros, 4 estilos, César obteve nos 4 estilos, respectivamente, os tempos 0:52.50, 1:02.12, 1:05.42 e 0:54.10. O tempo total de César, nessa prova, foi de',null,'[{"letter":"A","text":"3:54.14"},{"letter":"B","text":"3:44.24"},{"letter":"C","text":"3:14.44"},{"letter":"D","text":"2:44.04"},{"letter":"E","text":"2:24.54"}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q018','pmce-2021',18,'raciocinio-logico','Em um grupo de 120 soldados, 70 gostam de futebol e 60 gostam de dançar. É correto concluir que,',null,'[{"letter":"A","text":"no máximo, 10 soldados gostam de futebol e de dançar."},{"letter":"B","text":"no máximo, 50 soldados não gostam de futebol nem de dançar."},{"letter":"C","text":"no mínimo, 10 soldados não gostam de futebol nem de dançar."},{"letter":"D","text":"exatamente, 30 soldados gostam de futebol e de dançar."},{"letter":"E","text":"no mínimo, 60 soldados gostam de futebol e de dançar."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q019','pmce-2021',19,'raciocinio-logico','Um retângulo tem um de seus lados aumentado em 2/5 de seu valor e o outro lado diminuído de 1/4 de seu valor. Conclui-se que a área desse retângulo, em relação à área inicial,',null,'[{"letter":"A","text":"aumentou 3/20."},{"letter":"B","text":"aumentou 1/10."},{"letter":"C","text":"aumentou 1/20."},{"letter":"D","text":"diminuiu 3/20."},{"letter":"E","text":"diminuiu 1/5."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q020','pmce-2021',20,'raciocinio-logico','O raio de uma esfera aumentou 1/3 de seu valor. Sendo V o volume inicial da esfera, é correto afirmar que o novo volume',null,'[{"letter":"A","text":"é menor do que V."},{"letter":"B","text":"está entre V e (4/3)V."},{"letter":"C","text":"está entre (4/3)V e 2V."},{"letter":"D","text":"está entre 2V e 3V."},{"letter":"E","text":"é maior que 3V."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q021','pmce-2021',21,'atualidades-historia-do-ceara','O TPI (Tribunal Penal Internacional) é o órgão que julga crimes que toda a comunidade internacional está interessada que sejam punidos, tamanha é a sua gravidade. É o caso dos crimes contra a humanidade, expressão que designa atos desumanos contra uma população civil, que causem intencionalmente grande sofrimento ou afetem gravemente a integridade física ou a saúde física ou mental. Além disso, para serem considerados contra a humanidade, esse ataque contra a população civil tem de ser generalizado e realizado em larga escala ou deve ser sistemático, cometido de forma organizada e persistente. Quem comete o crime deve ter conhecimento de que o ataque se insere num contexto mais amplo de uma política (estatal ou de uma organização) contra aquela população. Com base no exposto, as condutas listadas a seguir podem ser consideradas exemplos de crimes contra a humanidade, à exceção de uma. Assinale-a.',null,'[{"letter":"A","text":"Extermínio de grupos indígenas."},{"letter":"B","text":"Escravização de trabalhadores."},{"letter":"C","text":"Desvio de verbas e fraude no erário público."},{"letter":"D","text":"Tortura e violência sexual dirigida a determinado grupo."},{"letter":"E","text":"Perseguição de um grupo em razão de sua identidade."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q022','pmce-2021',22,'atualidades-historia-do-ceara','Entre final de outubro e início de novembro de 2021, Glasgow (Escócia) sediará uma conferência para debater como controlar as mudanças climáticas, a COP26. A respeito do vocabulário ambientalista recorrente no encontro, relacione as expressões listadas a seguir às suas respectivas caracterizações. 1. Acordo de Paris 2. Justiça climática 3. Painel Intergovernamental sobre Mudanças Climáticas ( ) Avalia as pesquisas mais atualizadas sobre mudanças climáticas e produz relatórios não prescritivos para as negociações internacionais que visam ao enfrentamento da mudança do clima. ( ) Vincula direitos humanos e desenvolvimento, para salvaguardar os direitos das pessoas mais vulneráveis e partilhar os encargos das mudanças climáticas de forma equitativa. ( ) Estabelece a meta de manter o aquecimento global abaixo de 2°C acima dos níveis pré-industriais, e tentar atingir a meta de 1,5°C, para evitar catástrofes climáticas. Assinale a opção que apresenta a sequência correta, segundo a ordem estabelecida.',null,'[{"letter":"A","text":"1, 3 e 2."},{"letter":"B","text":"2, 3 e 1."},{"letter":"C","text":"3, 2 e 1."},{"letter":"D","text":"2, 1 e 3."},{"letter":"E","text":"1, 2 e 3."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q023','pmce-2021',23,'atualidades-historia-do-ceara','A entrada das mulheres na Polícia Militar se deu junto com o processo de redemocratização do país. A respeito da participação feminina na corporação, leia o trecho da entrevista de Tatiana Lima, Capitã da Polícia Militar do Rio de Janeiro, a seguir. Eu entrei em 2008, fiz a academia, me formei em 2010 e fui trabalhar nas ruas. Eu peguei um momento em que a entrada das mulheres nas UPPs foi muito valorizada, pois a imagem das policiais femininas ajudou muito na pacificação. A gente precisava do diálogo com a comunidade e as mulheres por serem mais humanas e acolhedoras conseguiram abrir esse espaço. Então, externamente foi bom. Internamente, principalmente nas missões operacionais, o preconceito continuou. A mulher continua sendo vista como mais fraca. Em uma operação com emprego de armas longas utilizadas em massa, sempre duvidam da performance da mulher. Hoje as mulheres estão começando a mostrar de forma positiva que também querem ocupar esse espaço. O importante é treinar e tentar igualar a eficiência da resposta física, apesar dos homens terem uma genética mais favorável. Tudo é treino. Adaptado de https://www.nexojornal.com.br/profissoes/2021/04/16 Segundo o testemunho da entrevistada, assinale a afirmativa correta.',null,'[{"letter":"A","text":"A isonomia de fato entre homens e mulheres na PM foi atingida, por isso a participação feminina está aumentando."},{"letter":"B","text":"O cargo de PM é incompatível com o gênero feminino, por envolver situações de confronto violento."},{"letter":"C","text":"A atuação feminina na PM é válida, mas deve ser direcionada preferencialmente para missões de pacificação."},{"letter":"D","text":"O preparo físico é fundamental para o serviço operacional, independente do gênero."},{"letter":"E","text":"O espaço para a mulher na PM é reduzido, tanto em ações de confronto quanto em atividades de relações públicas."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q024','pmce-2021',24,'atualidades-historia-do-ceara','Em 2021, depois de superada a fase mais aguda da pandemia, a cotação das commodities subiu e se somou ao desarranjo nas cadeias de produção. Essa interrupção provocou uma escassez de produtos, pressionando os preços. Assinale a opção que descreve corretamente um aspecto do atual cenário da economia brasileira.',null,'[{"letter":"A","text":"A alta das commodities valorizou o real em relação ao dólar, pois o Brasil é um grande exportador de produtos básicos, como soja e milho."},{"letter":"B","text":"O desarranjo no setor de bens de consumo duráveis foi causado pela alta na demanda externa, difícil de ser atendida pela escassez de matéria-prima vinda da China."},{"letter":"C","text":"O fortalecimento da moeda brasileira em relação ao dólar é o resultado das exportações do agronegócio, que continuou forte, mesmo com a crise global da pandemia."},{"letter":"D","text":"A desordem nas cadeias produtivas resultou da crise sanitária, que paralisou ou reduziu a produção em diversos setores industriais e gerou desabastecimento de insumos."},{"letter":"E","text":"A alta nos preços dos combustíveis e da energia elétrica elevou os custos de produção e causou o desarranjo das cadeias produtivas nacionais."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q025','pmce-2021',25,'atualidades-historia-do-ceara','Segundo o Financial Times, em agosto de 2021, a China testou, com relativo êxito, um míssil hipersônico. De acordo com as informações, o míssil hipersônico foi lançado pela China e circulou o globo terrestre, antes de acertar um alvo determinado, em terra. O míssil, que pode carregar em sua ponta uma ogiva nuclear, estava acoplado a um veículo planador capaz de alterar a própria rota para atingir o alvo. As agências de inteligência dos EUA estão surpresas com o progresso da potência asiática em armas de altíssimo alcance. Adaptado de https://canaltech.com.br/inovacao Com base no texto, analise as afirmativas a seguir. I. Mísseis hipersônicos são uma ameaça para os sistemas americanos de defesa contra mísseis, pois é difícil rastrear sua trajetória já que conseguem alterar a própria rota original. II. Mísseis que superam a velocidade do som são cobiçadas armas de guerra, por atingir alvos cada vez mais distantes e igualar os mísseis balísticos intercontinentais em velocidade e potência destrutiva. III. China e EUA protagonizam uma reedição da Guerra Fria na qual o discurso não é mais contra o comunismo, como na Guerra Fria contra os soviéticos, mas em favor da democracia, contra o regime autocrata de Pequim. Está correto o que se afirma em',null,'[{"letter":"A","text":"I, apenas."},{"letter":"B","text":"I e II, apenas."},{"letter":"C","text":"I e III, apenas."},{"letter":"D","text":"II e III, apenas."},{"letter":"E","text":"I, II e III."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q026','pmce-2021',26,'atualidades-historia-do-ceara','A ocupação do território cearense ocorreu tardiamente, ao contrário da rápida ocupação do litoral açucareiro, iniciada no século XVI. Somente no século XVII o interior do Ceará seria ocupado pelos portugueses. A colonização “tardia” do Ceará, em relação às capitanias de Pernambuco e Bahia, por exemplo, está relacionada aos fatores listados a seguir, à exceção de um. Assinale-o.',null,'[{"letter":"A","text":"O desconhecimento do território pelos europeus e a resistência indígena."},{"letter":"B","text":"O impacto de fatores naturais, como as correntes marítimas, que dificultavam o acesso ao território."},{"letter":"C","text":"O fato de o Ceará não estar inserido nas rotas das especiarias, do ouro ou das riquezas litorâneas."},{"letter":"D","text":"O fracasso em expulsar os franceses, que tomaram posse do território e construíram o Forte de São Sebastião."},{"letter":"E","text":"Os conflitos em função da pirataria e da presença de franceses e holandeses na região."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q027','pmce-2021',27,'atualidades-historia-do-ceara','Leia o fragmento a seguir. Está feita a nossa íntima união, quer de reciprocidade de sentimentos, quer de riscos e perigos. O Ceará não cede a Pernambuco em patriotismo e zelo da sua liberdade: ambas são províncias do Brasil, cheias de gás, e daqueles ilustres caracteres que a natureza gravou nos corações livres dos brasileiros honrados. Do papel junto verá V. Exª. os motivos que nos obrigarão a depor o Presidente do governo desta província dentro de quatorze dias. O senhor Pedro José da Costa Barros em tão pouco período de tempo tornou-se alvo dos ressentimentos desse povo brioso que já não sofre os enganos, e para melhor dizer, o descaramento do gabinete do Rio de Janeiro. Quis levar-nos como escravos nos ferros do despotismo, e pretendeu que o Ceará negasse a Pernambuco aqueles indispensáveis socorros que um irmão deve prestar a seu irmão consternado: propôs mesmo que nós fôssemos de todos opostos aos sentimentos dos [desolados] pernambucanos. O fragmento refere-se à participação do Ceará no movimento conhecido como',null,'[{"letter":"A","text":"Revolta da Cabanagem."},{"letter":"B","text":"Insurreição do Crato."},{"letter":"C","text":"Revolução Pernambucana."},{"letter":"D","text":"Confederação do Equador."},{"letter":"E","text":"Revolta da Balaiada."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q028','pmce-2021',28,'atualidades-historia-do-ceara','A respeito da criação da Superintendência do Desenvolvimento do Nordeste (Sudene), avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Sua instituição partiu da definição do espaço que seria compreendido como Nordeste e passaria a ser objeto da ação governamental: os estados do Ceará, Maranhão, Piauí, Rio Grande do Norte, Paraíba, Pernambuco, Alagoas, Sergipe, Bahia e parte de Minas Gerais. ( ) Sua criação resultou da percepção de que, mesmo com o processo de industrialização, crescia a diferença entre o Nordeste e o Centro-Sul do Brasil, sendo necessário haver uma intervenção direta e planejada na região, para incentivar o seu desenvolvimento. ( ) A Sudene foi criada como uma autarquia subordinada diretamente à Presidência da República, e sua secretaria executiva coube a Celso Furtado que, de 1959 a 1964, foi responsável pela estratégia de atuação do órgão. As afirmativas são, na ordem apresentada, respectivamente,',null,'[{"letter":"A","text":"V – F – F."},{"letter":"B","text":"V – V– F."},{"letter":"C","text":"F – V – F."},{"letter":"D","text":"F – F – V."},{"letter":"E","text":"V – V – V."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q029','pmce-2021',29,'atualidades-historia-do-ceara','Em depoimento recente, Maria do Perpétuo Socorro França, Secretaria de Proteção Social, Justiça, Mulheres e Direitos Humanos (SPS) do Ceará, relata as ações da Comissão Especial de Anistia, órgão vinculado à sua secretaria: “Estamos selando nosso compromisso, enquanto Estado, para com todos os ex-presos políticos que lutaram pela democracia no Ceará durante a Ditadura Militar. As indenizações representam também nosso pedido de desculpas aos homens e mulheres que foram perseguidos neste período e que merecem todo nosso respeito. Somos o único Estado a indenizar ex-presos políticos da ditadura, e isso, reflete nossa preocupação com a efetivação das políticas que garantam de fato, direitos, liberdade e dignidade ao nosso povo”. Sobre a Comissão Especial de Anistia, é correto afirmar que ela é o órgão responsável por',null,'[{"letter":"A","text":"analisar processos de pessoas detidas no Ceará sob acusação de ter participado de atividades políticas durante o período da ditadura militar."},{"letter":"B","text":"investigar casos de corrupção e desvio de verbas na administração pública estadual, durante o período da ditadura militar."},{"letter":"C","text":"promover um revisionismo histórico a respeito da gestão do estado durante o governo civil-militar dos anos 1961-1979, apurando a verdade dos fatos."},{"letter":"D","text":"avaliar a ideologia dos que exerceram algum tipo de militância política, cultural ou trabalhista no contexto da ditadura militar."},{"letter":"E","text":"indenizar todos os que foram presos injustamente no período do governo civil-militar e que possam demonstrar o erro cometido pelo judiciário."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q030','pmce-2021',30,'atualidades-historia-do-ceara','Em 1881, foi deflagrada a Greve dos Jangadeiros, liderada pelo pescador Francisco José do Nascimento, conhecido como o “dragão do mar”. O movimento recusava-se a embarcar, no porto de Fortaleza, os escravizados que seriam enviados às províncias do sul. Sobre o movimento dos jangadeiros em Fortaleza, assinale a afirmativa correta.',null,'[{"letter":"A","text":"Paralisou o mercado escravista do porto da cidade, obrigando o redirecionamento dos escravos para Belém."},{"letter":"B","text":"Tornou o Ceará a primeira província a abolir a escravidão, em 1881, antes da assinatura da Lei Áurea."},{"letter":"C","text":"Teve um papel na abolição da escravidão no Ceará, mas não conseguiu o apoio da elite intelectual abolicionista."},{"letter":"D","text":"Impactou o tráfico intercontinental de escravos, o que facilitou a imposição da Lei Eusébio de Queiroz."},{"letter":"E","text":"Foi comemorado pela imprensa abolicionistas na Corte, que difundiu o epíteto “dragão do mar”."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q031','pmce-2021',31,'administracao-publica-etica','A função pública deve ser exercida segundo os preceitos estabelecidos pela Administração Pública, tendo, como parâmetro, o Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal, materializado por meio do Decreto nº 1171/94. Com base no Decreto nº 1171/94, assinale a opção que indica um dever fundamental do servidor público.',null,'[{"letter":"A","text":"Postergar a prestação de contas, quando for necessário ao interesse social."},{"letter":"B","text":"Respeitar à igualdade, afastando-se de comportamentos que podem favorecer a hierarquia funcional."},{"letter":"C","text":"Apresentar-se ao trabalho com vestimentas que considere mais confortáveis."},{"letter":"D","text":"Facilitar a fiscalização de todos os atos ou serviços por quem de direito."},{"letter":"E","text":"Exercer suas atribuições com calma e tranquilidade, sem apressar-se diante de imprevistos."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q032','pmce-2021',32,'administracao-publica-etica','Ao longo da história, os estudos relacionados à ética deram origem a diversos conceitos e classificações sobre o termo. Acerca do apresentado, considere a situação na qual um policial, sozinho, encontra uma carteira no meio da rua, com elevada quantia em dinheiro, e decida devolvê-la a seu dono, em respeito ao dever, independentemente de qualquer recompensa ou risco de punição. Sobre a situação narrada, assinale a opção que indica o conceito de ética no qual se baseou a ação do policial.',null,'[{"letter":"A","text":"Relativista."},{"letter":"B","text":"Formal."},{"letter":"C","text":"Utilitarista."},{"letter":"D","text":"Empírico."},{"letter":"E","text":"Proporcional."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q033','pmce-2021',33,'administracao-publica-etica','Promover a motivação das pessoas que atuam nas organizações nem sempre é uma atividade trivial, tendo sido, por isso, objeto de diversos estudos por especialistas. Assinale a opção que se relaciona corretamente com a teoria motivacional dos dois fatores, de Frederick Herzberg.',null,'[{"letter":"A","text":"A satisfação das necessidades dos empregados deve ser realizada respeitando a hierarquia."},{"letter":"B","text":"Os comportamentos desejáveis devem ser incentivados por meio de reforços positivos."},{"letter":"C","text":"O grau de atividade da valência é responsável por propiciar ou não a expectativa."},{"letter":"D","text":"Os elementos higiênicos são responsáveis por evitar a insatisfação."},{"letter":"E","text":"A comparação com os pares é a base para a análise de compatibilidade entre os esforços e as retribuições."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q034','pmce-2021',34,'administracao-publica-etica','Com base nas características utilizadas usualmente para a conceituação dos termos ética e moral, assinale a afirmativa correta.',null,'[{"letter":"A","text":"A ética é uma normatização de comportamentos, enquanto a moral é uma disciplina filosófica."},{"letter":"B","text":"A ética possui caráter científico, enquanto a moral tem caráter prático."},{"letter":"C","text":"A ética possui caráter temporal, enquanto a moral tem caráter permanente."},{"letter":"D","text":"A ética está relacionada ao costume, enquanto a moral à qualidade do ser."},{"letter":"E","text":"A ética é cultural, enquanto a moral é teórica."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q035','pmce-2021',35,'administracao-publica-etica','No contexto da organização administrativa do Estado, e a responsabilidade pela instrumentalização das diretrizes estatais, a Polícia Militar do Ceará é um exemplo de',null,'[{"letter":"A","text":"órgão público."},{"letter":"B","text":"entidade administrativa."},{"letter":"C","text":"fundação concedente."},{"letter":"D","text":"entidade política."},{"letter":"E","text":"associação pública."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q036','pmce-2021',36,'administracao-publica-etica','Considere uma situação na qual o Governo do Ceará tenha a intenção de criar uma empresa pública de fomento, visando a auxiliar o desenvolvimento do Estado. Acerca dessa empresa pública, assinale a afirmativa correta.',null,'[{"letter":"A","text":"Será uma pessoa jurídica de direito privado, devendo sua criação ser autorizada por lei."},{"letter":"B","text":"Será uma pessoa jurídica de direito público, devendo ser criada por lei específica."},{"letter":"C","text":"Será um consórcio interno, devendo ser criado por decreto."},{"letter":"D","text":"Será uma delegatária, devendo ser instituída por convênio."},{"letter":"E","text":"Não possuirá personalidade jurídica, devendo ter a criação autorizada por portaria."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q037','pmce-2021',37,'administracao-publica-etica','Acerca da organização administrativa, analise as afirmativas a seguir. I. As autarquias devem ser criadas com o objetivo precípuo de explorar atividade econômica de utilidade pública. II. As fundações públicas possuem natureza jurídica de organização social. III. As sociedades de economia mista podem ser responsáveis pela prestação de serviços públicos. Está correto o que se afirma em',null,'[{"letter":"A","text":"I, apenas."},{"letter":"B","text":"II, apenas."},{"letter":"C","text":"III, apenas."},{"letter":"D","text":"I e II, apenas."},{"letter":"E","text":"I e III, apenas."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q038','pmce-2021',38,'administracao-publica-etica','As agências reguladoras são importantes inovações do Estado brasileiro, idealizadas, no contexto da reforma gerencial de 1995, com o intuito de regular atividades de determinados setores da economia. Acerca das agências reguladoras, é correto afirmar que elas foram criadas por meio do processo conhecido por',null,'[{"letter":"A","text":"desconcentração."},{"letter":"B","text":"concentração."},{"letter":"C","text":"descentralização."},{"letter":"D","text":"centralização."},{"letter":"E","text":"privatização."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q039','pmce-2021',39,'administracao-publica-etica','Embora cada empresa tenha sua peculiaridade, existem atividades que são indispensáveis para os gestores, sendo conhecidas como funções administrativas. Assinale a opção que apresenta corretamente as funções administrativas.',null,'[{"letter":"A","text":"Planejamento, organização, coordenação e coerção."},{"letter":"B","text":"Planejamento, organização, direção e controle."},{"letter":"C","text":"Organização, coordenação, controle e inovação."},{"letter":"D","text":"Coordenação, decisão, motivação e planejamento."},{"letter":"E","text":"Direção, premeditação, coerção e coordenação."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q040','pmce-2021',40,'administracao-publica-etica','Ao analisar a estrutura de uma organização típica, é possível identificar a existência de três níveis hierárquicos: o tático, o operacional e o estratégico. Sabendo que cada um desses níveis é responsável por funções específicas na estrutura organizacional, o nível operacional tem foco, essencialmente, no',null,'[{"letter":"A","text":"longo prazo e em unidades específicas."},{"letter":"B","text":"longo prazo e nas diretrizes departamentais."},{"letter":"C","text":"médio prazo no ambiente interno."},{"letter":"D","text":"curto prazo e no ambiente externo."},{"letter":"E","text":"curto prazo e em tarefas."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q041','pmce-2021',41,null,'Maria, policial militar, constatou que parte do telhado de uma casa localizada em comunidade carente, em razão das fortes chuvas ocorridas na região, tinha desabado. Apesar do desabamento, o muro e o portão ao redor da casa, bem como suas paredes, permaneciam hígidos. À luz dessa narrativa, caso Maria identifique a existência de pessoa ferida no interior da casa, não estando presente outra que possa ajudá-la, ela',null,'[{"letter":"A","text":"deve aguardar a chegada de outro morador e solicitar sua autorização para ingressar no local."},{"letter":"B","text":"deve comparecer perante o juízo da região e solicitar autorização para ingressar no local."},{"letter":"C","text":"pode apenas isolar a área e aguardar o órgão de salvamento, que está legalmente autorizado a ingressar no local."},{"letter":"D","text":"deve se comunicar com a pessoa ferida e, somente se ela exteriorizar seu consentimento, ingressar no local."},{"letter":"E","text":"pode ingressar no local, mesmo sem autorização do morador ou ordem judicial, para prestar socorro à pessoa ferida."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q042','pmce-2021',42,null,'Com o objetivo de estimular a abertura de igrejas, o que, ao ver dos idealizadores do projeto, contribuiria para aumentar o bemestar da população, o Estado Alfa editou a Lei nº XX. De acordo com esse diploma normativo, as igrejas que preenchessem os requisitos exigidos teriam subvencionadas 50% de suas despesas regulares. Considerando a sistemática constitucional, é correto afirmar que a Lei nº XX é',null,'[{"letter":"A","text":"inconstitucional, em razão do caráter laico dos entes federativos."},{"letter":"B","text":"constitucional, em razão do elevado interesse público a ser atendido com a iniciativa."},{"letter":"C","text":"constitucional, pois é dever do Estado prestigiar a liberdade de crença, subvencionando as igrejas."},{"letter":"D","text":"inconstitucional, salvo se for assegurado que a subvenção alcance, de forma igualitária, todas as religiões."},{"letter":"E","text":"inconstitucional, pois a subvenção foi parcial e as entidades sem fins lucrativos devem recebê-la de modo integral."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q043','pmce-2021',43,null,'João foi condenado a quatro anos de prisão, substituídos por pena restritiva de direitos por igual período, em sentença criminal transitada em julgado. Como pretende concorrer a cargo eletivo na eleição a ser realizada no ano seguinte, consultou um advogado sobre essa possibilidade, o qual lhe respondeu, corretamente, que a referida condenação, enquanto produzir efeitos,',null,'[{"letter":"A","text":"impede João de concorrer a cargo eletivo somente no local em que foi proferida a sentença."},{"letter":"B","text":"não produz efeitos no âmbito eleitoral, em razão da independência das instâncias."},{"letter":"C","text":"apenas impede João de ocupar um cargo público, eletivo ou não."},{"letter":"D","text":"impede João de votar e ser votado."},{"letter":"E","text":"apenas impede João de ser votado."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q044','pmce-2021',44,null,'Joana, recém-eleita deputada estadual, pretendia apresentar um projeto de lei em matéria na qual, conforme a ordem constitucional, há competência legislativa concorrente entre a União e os Estados. Ao questionar sua assessoria sobre as características dessa espécie de competência, ela foi informada, corretamente, que',null,'[{"letter":"A","text":"o Estado deve observar as normas gerais editadas pela União."},{"letter":"B","text":"as normas devem ser editadas em conjunto pela União e pelos Estados."},{"letter":"C","text":"o Estado exerce a competência legislativa plena e, a União, a competência subsidiária."},{"letter":"D","text":"o Estado pode legislar livremente sobre a matéria no âmbito local e a União no âmbito nacional."},{"letter":"E","text":"a norma específica editada pelo Estado prevalece sobre a norma geral da União, na hipótese de conflito."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q045','pmce-2021',45,null,'Jéssica, vereadora no Município Alfa, realizou sérias críticas ao sistema de transporte público de caráter coletivo oferecido aos munícipes. Na ocasião, ela afirmou que, além de a qualidade ser sofrível, não eram revertidos, em benefícios para a coletividade, as inúmeras vantagens oferecidas pelo Poder Público às sociedades empresárias do setor, que “sangravam os cofres públicos e a coletividade sem piedade”. Insatisfeitas, essas sociedades, no afã de promover a responsabilidade civil de Jéssica, procuraram a orientação de um advogado, que lhes respondeu, corretamente, que',null,'[{"letter":"A","text":"a responsabilização de Jéssica somente seria possível caso sua opinião tivesse sido emitida fora do recinto da Câmara Municipal de Alfa."},{"letter":"B","text":"Jéssica, diversamente dos parlamentares federais e estaduais, não tinha inviolabilidade por suas opiniões e palavras, sendo possível responsabilizá-la."},{"letter":"C","text":"Jéssica tinha inviolabilidade idêntica à dos parlamentares federais e estaduais por suas opiniões e palavras, não sendo possível responsabilizá-la."},{"letter":"D","text":"a inviolabilidade de Jéssica somente alcançava as opiniões e palavras proferidas no exercício do mandato e na circunscrição do Município."},{"letter":"E","text":"a responsabilização de Jéssica estava condicionada ao fato de sua opinião não ter sido referendada, por maioria simples, pelos membros da Câmara Municipal de Alfa."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q046','pmce-2021',46,null,'Pedro, estudante de direito, questionou seu professor de direito constitucional a respeito de diversos aspectos relacionados ao órgão competente para processar e julgar o Presidente da República, caso ele seja acusado da prática de crime de responsabilidade. O professor respondeu corretamente que esse órgão é o(a)',null,'[{"letter":"A","text":"Senado Federal."},{"letter":"B","text":"Congresso Nacional."},{"letter":"C","text":"Câmara dos Deputados."},{"letter":"D","text":"Supremo Tribunal Federal."},{"letter":"E","text":"Conselho Nacional de Justiça."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q047','pmce-2021',47,null,'O Presidente da República recebeu sugestão de um assessor no sentido de que deveria ser editada medida provisória a respeito de certa matéria. Ao questioná-lo sobre os requisitos a serem observados na edição desse ato normativo, o assessor respondeu, corretamente, que ele',null,'[{"letter":"A","text":"deve ser precedido de autorização do Congresso Nacional."},{"letter":"B","text":"pode ser editado em qualquer matéria de interesse público, em caso de urgência."},{"letter":"C","text":"não é suscetível de apreciação pelo Congresso Nacional e produz efeitos por 60 dias."},{"letter":"D","text":"pode ser editado em qualquer matéria de interesse público que exija disciplina uniforme."},{"letter":"E","text":"deve ser posteriormente apreciado pelo Congresso Nacional, perdendo sua eficácia caso não o seja."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q048','pmce-2021',48,null,'A Associação de Moradores do pequeno Município Alfa, insatisfeita com a conduta e com diversas decisões proferidas pelo Juiz de Direito da Comarca que abrangia esse Município, consultou um advogado sobre a possibilidade de ser requerida a remoção compulsória do referido magistrado, o que seria de suma importância para o bem-estar da coletividade. O advogado respondeu, corretamente, que essa medida',null,'[{"letter":"A","text":"depende de sentença judicial transitada em julgado."},{"letter":"B","text":"exige decisão do respectivo Tribunal, referendada pelo Supremo Tribunal Federal."},{"letter":"C","text":"é incompatível com a ordem constitucional, em razão da garantia da inamovibilidade."},{"letter":"D","text":"exige decisão por voto da maioria absoluta do respectivo Tribunal ou do Conselho Nacional de Justiça."},{"letter":"E","text":"depende de prévia consulta à população local, daí decorrendo a instauração do processo próprio."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q049','pmce-2021',49,null,'Inácio dos Santos, servidor da Promotoria de Justiça da Comarca Beta, recebeu a incumbência de separar as representações, encaminhadas ao Ministério Público, que versassem sobre a tutela de interesses difusos. Entre as representações recebidas, estavam as indicadas a seguir. I. A primeira tratava de vazamento de resíduos sólidos de uma siderúrgica no Rio XX, comprometendo a pesca no local. II. A segunda tratava do aumento abusivo das mensalidades da escola particular YY. III. A terceira tratava do incômodo de um vizinho devido ao som na casa do vizinho limítrofe. Para atender à solicitação, Inácio deve separar as manifestações',null,'[{"letter":"A","text":"I e III, apenas."},{"letter":"B","text":"I e II, apenas."},{"letter":"C","text":"I, apenas."},{"letter":"D","text":"II, apenas."},{"letter":"E","text":"III, apenas."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q050','pmce-2021',50,null,'João, pessoa violenta, passou a adotar comportamento que expunha sua esposa, Maria, a iminente risco de vida. Nessa situação, João pode ser afastado do lar conjugal',null,'[{"letter":"A","text":"apenas pela autoridade judicial, ainda que o Município não seja sede de comarca."},{"letter":"B","text":"pelo delegado de polícia, caso o Município não seja sede de comarca, com comunicação ao juízo competente."},{"letter":"C","text":"pelo delegado de polícia ou por policial, com prévia anuência do Ministério Público, caso a medida seja urgente."},{"letter":"D","text":"pela autoridade judicial, pelo Ministério Público ou pelo delegado de polícia, conforme a precedência na ciência dos fatos."},{"letter":"E","text":"pelo Ministério Público ou pelo delegado de polícia, caso o Município não seja sede de seção judiciária, com comunicação ao juízo competente."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q051','pmce-2021',51,null,'Populares solicitaram que uma guarnição da polícia militar comparecesse ao restaurante XX. Lá chegando, constataram que o segurança do estabelecimento estava negando o ingresso de um grupo de pessoas de cor negra, sob o argumento de que parte do restaurante estava ocupada pelos seguidores de determinada religião que considerava pecado a convivência interracial. À luz desse quadro, os policiais militares devem',null,'[{"letter":"A","text":"prender o segurança do estabelecimento em razão da prática de crime."},{"letter":"B","text":"orientar os envolvidos a buscar uma solução de caráter conciliatório."},{"letter":"C","text":"informar ao segurança que apenas o eventual uso da força caracterizaria a prática de crime."},{"letter":"D","text":"assegurar que o grupo de pessoas de cor negra possa ingressar no restaurante em outro horário."},{"letter":"E","text":"orientar o grupo de pessoas de cor negra a procurar outro restaurante, em respeito à liberdade religiosa."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q052','pmce-2021',52,null,'Jeferson foi preso por estar comercializando substâncias entorpecentes de uso proibido. Na ocasião, entendeu que um, entre os diversos policiais militares que participaram da prisão, tinha se excedido. Por essa razão, solicitou que esse policial se identificasse, de modo que pudesse adotar as medidas legais que entendesse cabíveis na espécie. O policial, no entanto, negou a identificação solicitada. Nesse caso, a negativa de identificação do policial foi',null,'[{"letter":"A","text":"incorreta, configurando a prática de crime."},{"letter":"B","text":"correta, considerando a necessidade de resguardar sua segurança."},{"letter":"C","text":"correta, se amparada em orientação formal do seu comandante."},{"letter":"D","text":"incorreta, podendo acarretar apenas a responsabilização administrativa do policial, não a criminal."},{"letter":"E","text":"correta, considerando que a prisão, por força do princípio da impessoalidade, é sempre atribuída à polícia militar."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q053','pmce-2021',53,'direito-penal-militar-processo-penal-militar','Sobre o crime militar de abuso de autoridade, assinale a afirmativa correta.',null,'[{"letter":"A","text":"Conforme previsão legal expressa, os institutos despenalizadores da Lei nº 9.099/1995 aplicam-se ao crime militar de abuso de autoridade."},{"letter":"B","text":"Apesar do disposto na Súmula 172 do STJ, a partir da edição da Lei nº 13.491/2017, é possível que a Justiça Militar processe e julgue militar pelo crime militar de abuso de autoridade."},{"letter":"C","text":"Constranger um padre, sob ameaça de prisão, a depor no interior do quartel para expor detalhes de uma confissão de um policial militar, não configura crime militar de abuso de autoridade."},{"letter":"D","text":"O crime militar de abuso de autoridade não comporta a pessoa jurídica como sujeito passivo do crime."},{"letter":"E","text":"Compete ao Conselho de Justiça processar e julgar crime militar de abuso de autoridade cometido por policial militar contra civil."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q054','pmce-2021',54,'direito-penal-militar-processo-penal-militar','Com relação ao crime militar de tortura, assinale a afirmativa incorreta.',null,'[{"letter":"A","text":"O sargento que presencia a tortura de outro militar por um cabo, e nada fizer para impedi-lo, praticará o crime militar de tortura, incorrendo no mesmo tipo penal e pena que o cabo, em coautoria."},{"letter":"B","text":"O bem jurídico tutelado no crime de tortura é a dignidade da pessoa humana, visto que este tipo penal visa proteger tanto a integridade física quanto psíquica do ser humano."},{"letter":"C","text":"A ação penal no crime militar de tortura será sempre pública incondicionada."},{"letter":"D","text":"O crime de tortura é inafiançável e insuscetível de graça ou anistia."},{"letter":"E","text":"Se da prática do crime militar de tortura resultar lesão corporal grave, a pena aplicada será a de reclusão de quatro a dez anos."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q055','pmce-2021',55,'direito-penal-militar-processo-penal-militar','Sobre concurso de agentes, com base no Código Penal Militar, assinale a afirmativa correta.',null,'[{"letter":"A","text":"Em regra, as circunstâncias de caráter pessoal se comunicam a todos aqueles que concorrem para a prática do crime militar."},{"letter":"B","text":"O oficial que instiga seus inferiores a cometer o delito, sem dar ordem direta ou organizar a ação criminosa, terá sua pena atenuada se o crime for consumado, pois é uma hipótese de participação de somenos importância."},{"letter":"C","text":"Tratando-se de coautoria, a punibilidade de um dos agentes depende da dos demais de modo que a absolvição de um se comunica aos demais réus."},{"letter":"D","text":"Quem, de qualquer modo, concorre para o crime incide nas penas a este cominadas."},{"letter":"E","text":"Se o crime for praticado com o concurso de dois ou mais oficiais, a pena desses oficiais deverá ser aplicada em dobro."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q056','pmce-2021',56,'direito-penal-militar-processo-penal-militar','Com relação ao crime de deserção, assinale a afirmativa incorreta.',null,'[{"letter":"A","text":"Quando a ausência se verificar em subunidade isolada ou em destacamento, o respectivo comandante, oficial ou não, providenciará o inventário do desertor, devendo assinar com duas testemunhas idôneas."},{"letter":"B","text":"É um crime de perigo abstrato, uma vez que o risco advindo da conduta é presumida por lei, bastando a violação da norma para sua concretização."},{"letter":"C","text":"A contagem para a consumação do estado de ausência iniciase a partir de zero hora do dia seguinte àquela em que é verificada a falta injustificada do militar."},{"letter":"D","text":"Uma vez que o desertor com estabilidade se apresente ao quartel, ele deverá ser submetido à inspeção de saúde e, quando julgado apto, será reincluído."},{"letter":"E","text":"A deserção é crime de mera conduta, porque se configura com a ausência sem licença pura e simples do militar, além do prazo estabelecido em lei."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q057','pmce-2021',57,'direito-penal-militar-processo-penal-militar','Sobre as penas previstas no Código Penal Militar, assinale a afirmativa correta.',null,'[{"letter":"A","text":"A pena de impedimento, aplicável à maioria dos crimes propriamente militares, sujeita o condenado a permanecer no quartel, sem prejuízo da instrução militar."},{"letter":"B","text":"Apesar de prevista no Código Penal Militar, a pena de morte não pode ser aplicada por vedação constitucional."},{"letter":"C","text":"São circunstâncias que sempre agravam a pena, quando não integrantes ou qualificativas do crime, ter o agente cometido o crime militar enquanto estava de serviço ou contra grávida, criança, velho ou enfermo, conforme previsão expressa no Código Penal Militar."},{"letter":"D","text":"A pena de inabilitação para o exercício de função pública pode ser aplicada pelo prazo de 2 a 20 anos, em virtude de crime militar praticado com abuso de poder ou violação do dever militar, mas está condicionada a estar expressamente imposta na sentença."},{"letter":"E","text":"A suspensão dos direitos políticos, prevista como pena acessória no Código Penal Militar, perdura enquanto o condenado estiver inabilitado para o exercício de função pública e, como consequência, o condenado pode votar mas não pode ser votado."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q058','pmce-2021',58,'direito-penal-militar-processo-penal-militar','O soldado Castro, militar da Polícia Militar do Estado do Ceará, pratica um delito durante a vigência de uma lei temporária. A referida lei determina que a pena do delito será agravada se o crime tiver sido praticado por militar. Ocorre que, na época de seu julgamento, a mencionada lei já não estava em vigor. Sobre a situação descrita, com base no disposto no Código Penal Militar, assinale a afirmativa correta.',null,'[{"letter":"A","text":"Durante o julgamento, deve ser observada a lei mais benéfica para o réu."},{"letter":"B","text":"Durante o julgamento, deve ser aplicada a lei vigente."},{"letter":"C","text":"A lei temporária só será aplicada se for mais benéfica ao réu."},{"letter":"D","text":"A lei temporária, após o período de vigência, será aplicada ao fato ocorrido durante sua vigência, ainda que mais gravosa."},{"letter":"E","text":"A lei temporária não pode mais ser aplicada, uma vez decorrido seu período de vigência."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q059','pmce-2021',59,'direito-penal-militar-processo-penal-militar','Com base no Direito Penal Militar, assinale a afirmativa incorreta.',null,'[{"letter":"A","text":"O soldado José e o cabo Lima tiveram um desentendimento que culminou com José dando um soco no seu superior, que sofreu ferimentos leves. Com medo de represália, o soldado não comparece ao quartel por 10 dias. Sua esposa, Gabriela, empresta seu carro a José, para que ele possa se esconder em uma cabana em local ermo, dificultando a captura do soldado. É correto afirmar que Gabriela não responderá pelo crime de favorecimento a desertor."},{"letter":"B","text":"O soldado Batalha tenta subtrair para si o celular pertencente ao soldado Allan, mas antes que o delito de concretize, o soldado Batalha é pego pela sargento Aline. Enfurecido e inconformado com a tentativa de furto de um colega de farda, o soldado Allan se vinga, atropelando o pé do soldado Batalha com seu carro, o que lhe causa incapacidade para tirar serviço por 2 meses. Nesse caso, o soldado Batalha responderá pelo crime de furto, em sua forma tentada, enquanto o soldado Allan responderá pelo crime de lesão grave."},{"letter":"C","text":"Tendo em vista a festa de comemoração de seu aniversário, o soldado Eduardo instiga o soldado Ulysses a abandonar seu posto 1 hora antes do término do serviço. Inicialmente, o soldado Ulysses concorda em abandonar o posto para ir à festa, porém acaba desistindo e cumprindo o serviço regularmente. Nesse caso, o soldado Eduardo responderá pelo crime de instigação a abandono de posto."},{"letter":"D","text":"Com a intenção de formar um motim em protesto ao comandante do quartel, os soldados Franco e Allyson reúnem um grupo de 10 militares para ocupar a unidade militar. Para todos saberem a seriedade do protesto, o soldado Allyson sugere o uso de armas. Assim, metade dos militares faz a ocupação, portando arma de forma ostensiva e todos ocupam o quartel por dois dias. Nesse caso, é correto afirmar que todos responderão pelo crime de revolta."},{"letter":"E","text":"Após ser desrespeitada pelo soldado Bruno, a tenente Patrícia ameaça lavrar uma comunicação disciplinar ao comandante do quartel. A conduta da tenente Patrícia não caracteriza ameaça, ainda que seja provado que não houve desrespeito por parte do soldado Bruno."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q060','pmce-2021',60,'direito-penal-militar-processo-penal-militar','Com base no Código Penal Militar, avalie as afirmativas a seguir. I. Para se reconhecer qual é a mais favorável, a lei posterior e a anterior devem ser consideradas separadamente, cada qual no conjunto de suas normas aplicáveis. II. O Código Penal Militar adota a teoria mista em relação ao tempo do crime, considerando-se praticado o crime tanto no momento da conduta ou omissão, quanto no momento do resultado do crime. III. Se uma lei posterior deixar de considerar um fato de um crime, nenhum agente poderá ser punido, salvo se já tiver sido condenado por sentença irrecorrível. Está correto o que se afirma em',null,'[{"letter":"A","text":"I, apenas."},{"letter":"B","text":"II, apenas."},{"letter":"C","text":"I e II, apenas."},{"letter":"D","text":"I e III, apenas."},{"letter":"E","text":"II e III, apenas."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q061','pmce-2021',61,'direito-penal-militar-processo-penal-militar','Com base no Código Penal Militar, assinale a afirmativa que é classificada como pena acessória.',null,'[{"letter":"A","text":"Suspensão do exercício do posto, da graduação, do cargo ou da função."},{"letter":"B","text":"Perda do posto e da patente."},{"letter":"C","text":"Reforma."},{"letter":"D","text":"Detenção."},{"letter":"E","text":"Impedimento."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q062','pmce-2021',62,'direito-penal-militar-processo-penal-militar','Com base no Código Penal Militar, avalie as afirmativas a seguir. I. O erro de direito do Código Penal Militar está relaciona com a ignorância ou falsa interpretação da lei. A regra castrense diverge da do Código Penal Comum, uma vez que mesmo sendo escusável, o erro não exclui o dolo, mas apenas atenua ou permite a substituição da pena. II. O erro de fato do Código Penal Militar não isenta o agente de pena, pois ao incidir sobre o fato que constitui o crime não importa se o erro é escusável ou inescusável, causando apenas uma atenuação da pena em medida proporcional ao erro. III. Nos crimes em que há violação do dever militar, as únicas hipóteses de coação, que podem ser invocadas pelo agente, são de ordem física ou material. Está correto o que se afirma em',null,'[{"letter":"A","text":"I, apenas."},{"letter":"B","text":"II, apenas."},{"letter":"C","text":"III, apenas."},{"letter":"D","text":"I e II, apenas."},{"letter":"E","text":"I e III, apenas."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q063','pmce-2021',63,'direito-penal-e-processual-penal','Otávio foi preso em flagrante e, posteriormente, sua prisão foi convertida em temporária, em razão de ter sido encontrado portando uma arma de fogo de uso restrito, tendo a autoridade policial enquadrado a sua conduta no crime previsto no Art. 16 da Lei nº 10.826/03. Com relação à duração da prisão temporária de Otávio, assinale a afirmativa correta.',null,'[{"letter":"A","text":"Terá a duração de 60 dias, podendo ser prorrogada por igual período em caso de extrema e comprovada necessidade."},{"letter":"B","text":"Terá a duração de 5 dias prorrogáveis por mais 5, uma vez que não se trata de crime hediondo."},{"letter":"C","text":"Terá a duração de 15 dias prorrogáveis por mais 15, em caso de extrema e comprovada necessidade, por se tratar de crime hediondo."},{"letter":"D","text":"Terá a duração de 90 dias, devendo ser relaxada ao término do referido prazo, caso não haja renovação de seus fundamentos por parte do Ministério Público."},{"letter":"E","text":"Terá a duração de 30 dias, prorrogáveis por mais 30, em caso de extrema e comprovada necessidade."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q064','pmce-2021',64,'direito-penal-e-processual-penal','João, policial militar, responde a Inquérito policial pela prática do crime de abuso de autoridade, por ter violado o domicílio de Mário, em 7 de junho de 2019, sem estar respaldado pelo respectivo Mandado de Busca e Apreensão. A autoridade policial indicia João pela prática do crime previsto no Art. 3º, alínea b, da Lei nº 4.898/65, que trata do atentado contra a inviolabilidade de domicílio, cuja pena é de detenção de 10 dias a 6 meses. Uma vez relatado o Inquérito, este é remetido para o Ministério Público para o oferecimento da denúncia. Em virtude da entrada em vigor da Lei nº 13.869/19, o promotor com atribuição oferece denúncia contra João, imputando, a ele, a prática do crime previsto no Art. 22 da nova Lei, que trata da mesma figura criminal, qual seja, a conduta de violar o domicílio sem obedecer às formalidades legais, cuja pena é detenção de 1 a 4 anos. Acerca da conduta do promotor, assinale a afirmativa correta.',null,'[{"letter":"A","text":"Está correta, uma vez que a irretroatividade da lei penal mais severa vale apenas para processos já em curso, não se aplicando para casos em que a ação não tenha sido proposta."},{"letter":"B","text":"Está correta, uma vez que a nova lei de abuso de autoridade retroage aos fatos anteriores, mesmo que a pena cominada seja maior do que a anterior."},{"letter":"C","text":"Está correta, uma vez que em relação à lei no tempo, o Direito Penal adota a teoria da ubiquidade, valendo a lei que estava em vigor na data da propositura da ação, pouco importando a lei em vigor na data do fato."},{"letter":"D","text":"Está incorreta, uma vez que a lei penal mais severa jamais retroage, mesmo em caso de crimes permanentes e crimes continuados."},{"letter":"E","text":"Está incorreta, em razão do princípio da irretroatividade da lei penal mais severa, sendo certo que esta regra apenas admite exceção em casos de crime permanente e crime continuado, o que não é o caso de João."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q065','pmce-2021',65,'direito-penal-e-processual-penal','A polícia civil instaurou inquérito para investigar os delitos de tráfico de drogas e associação para o tráfico (artigos 33 e 35 da Lei nº 11.343/06), após a prisão em flagrante de Marcos e Mateus que, ao serem abordados, levavam consigo 2 quilos de maconha, cada um, e foram, assim, indiciados. A substância apreendida foi identificada por laudo de constatação provisório, elaborado por dois peritos não oficiais. Marcos e Mateus, por sua vez, tiveram a prisão em flagrante convertida em preventiva, ficando presos durante as investigações. Sobre o procedimento do caso apresentado, assinale a afirmativa correta.',null,'[{"letter":"A","text":"O inquérito policial em questão deve ser concluído no prazo máximo de 90 dias, podendo ser duplicado pelo juiz, a pedido da autoridade policial, ouvido o Ministério Público."},{"letter":"B","text":"A Lei nº 11.343/06 dispõe que o laudo provisório só poderia ser elaborado por perito oficial."},{"letter":"C","text":"O inquérito policial em questão deve ser concluído no prazo máximo de 10 dias, podendo ser prorrogado pelo juiz, a pedido da autoridade policial, ouvido o Ministério Público."},{"letter":"D","text":"O inquérito policial em questão deve ser concluído no prazo máximo de 30 dias, podendo ser duplicado pelo juiz, a pedido da autoridade policial, ouvido o Ministério Público."},{"letter":"E","text":"A lei não exige a elaboração de laudo de constatação provisório para efeito de lavratura do auto de prisão em flagrante e estabelecimento da materialidade delitiva."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q066','pmce-2021',66,'direito-penal-e-processual-penal','Pedro sofre escoriações no rosto após receber um soco de seu irmão João, durante uma discussão em um almoço familiar. Fica indeciso sobre comunicar o fato à polícia, e sua namorada, Mariana, inconformada, dirige-se à delegacia, onde faz notícia crime contra João. A autoridade policial imediatamente instaura inquérito para apurar o delito de lesão corporal leve qualificada pela violência doméstica, nos termos do Art. 129, § 9º, do Código Penal. O crime em questão é punido com pena de detenção de três meses a três anos, sendo a ação penal pública condicionada à representação. Com base nos dados fornecidos, assinale a afirmativa correta.',null,'[{"letter":"A","text":"O delegado de polícia não pode instaurar inquérito, assim como o Ministério Público não pode oferecer denúncia sem a representação de Pedro."},{"letter":"B","text":"Embora a autoridade policial possa instaurar inquérito, o Ministério Público não pode oferecer denúncia sem a representação de Pedro."},{"letter":"C","text":"O inquérito pode ser instaurado pela autoridade policial e o Ministério Público pode oferecer denúncia, independentemente da manifestação de Pedro, pois trata-se de ação penal pública."},{"letter":"D","text":"O delegado de polícia não pode instaurar inquérito sem a representação de Pedro, mas o Ministério Público pode oferecer denúncia, ainda que a vítima não tenha manifestado seu interesse em ver instaurada a persecução."},{"letter":"E","text":"Ainda que a vítima seja homem, por se tratar de violência praticada contra irmão no âmbito doméstico, o delegado pode instaurar inquérito e o Ministério Público pode oferecer denúncia sem a manifestação da vítima."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q067','pmce-2021',67,'direito-penal-e-processual-penal','Leonardo, primário, é preso em flagrante, no dia 20 de junho de 2021, pela prática do crime de roubo simples, na forma do Art. 157, caput, do Código Penal. O crime é punido com pena de 4 a 10 anos de reclusão e multa. Lavrado auto de prisão em flagrante e feitas as comunicações devidas, o preso é conduzido, em 12 horas, à presença de juiz para a realização de audiência de custódia. Nessa ocasião, o promotor de justiça pede a concessão da liberdade provisória com a imposição de medidas cautelares diversas da prisão. O juiz homologa a prisão em flagrante e decreta, de ofício, a prisão preventiva de Leonardo. Sobre o caso narrado, assinale a afirmativa correta.',null,'[{"letter":"A","text":"O juiz não poderia ter decretado a prisão preventiva, pois essa medida é incabível em razão da pena máxima cominada ao crime de roubo."},{"letter":"B","text":"O juiz poderia ter decretado a prisão preventiva de ofício, pois não cabia a liberdade provisória pela pena cominada."},{"letter":"C","text":"Como o Ministério Público pediu a liberdade provisória, o juiz não poderia ter decretado a prisão preventiva de ofício."},{"letter":"D","text":"O juiz só poderia decretar a prisão preventiva de ofício após o oferecimento de denúncia pelo Ministério Público."},{"letter":"E","text":"Leonardo não poderia ter sido preso preventivamente, pois é primário."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q068','pmce-2021',68,'direito-penal-e-processual-penal','Alberto foi preso preventivamente pela prática do crime de corrupção passiva, tendo a autoridade judiciária justificado a prisão na garantia da ordem pública, nos termos do pedido formulado pelo Ministério Público e em atenção aos ditames do Art. 312 do Código de Processo Penal. Após 4 meses de prisão, os familiares de Alberto procuram um advogado informando que o processo se encontrava parado desde a decretação da prisão, não tendo o Magistrado, ou o Ministério Público, feito qualquer manifestação desde então. A partir das informações apresentadas e com base exclusivamente na atual redação do Código de Processo Penal, assinale a afirmativa correta.',null,'[{"letter":"A","text":"Nada poderá ser feito em favor de Alberto, uma vez que a prisão preventiva não tem prazo, podendo durar por tempo indeterminado até a revogação por parte do juiz."},{"letter":"B","text":"Nada poderá ser feito, uma vez que o Magistrado só precisa reanalisar os fundamentos da prisão preventiva após o transcurso de 180 dias, o que não se verificou na hipótese de Alberto."},{"letter":"C","text":"Nada poderá ser feito uma vez que o Magistrado só precisa reanalisar os fundamentos da prisão preventiva após o transcurso de 150 dias, o que não se verificou na hipótese de Alberto."},{"letter":"D","text":"O advogado deverá formular pedido de relaxamento de prisão, uma vez que o Ministério Público deveria ter renovado a necessidade de manutenção da prisão preventiva após 90 dias, o que, por não ter sido feito, torna a prisão ilegal."},{"letter":"E","text":"O advogado deverá formular pedido de relaxamento de prisão, uma vez que o Ministério Público deveria ter renovado a necessidade de manutenção da prisão preventiva após 60 dias, o que, por não ter sido feito, torna a prisão ilegal."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q069','pmce-2021',69,'criminologia','Acerca das Escolas da Criminologia, assinale a afirmativa correta.',null,'[{"letter":"A","text":"A Escola da Criminologia Clássica tem ênfase na implementação de políticas criminais preventivas."},{"letter":"B","text":"A Escola da Criminologia Científica Moderna tem como principais teóricos Césare Lombroso, Enrico Ferri e Rafael Garófalo."},{"letter":"C","text":"A Escola da Criminologia Crítica analisa a seletividade e propõe a deslegitimação do sistema penal."},{"letter":"D","text":"A Escola da Criminologia Positivista tem como principal expoente Césare Beccaria."},{"letter":"E","text":"A Escola da Criminologia Positivista rechaça a análise científica sobre a criminalidade."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q070','pmce-2021',70,'criminologia','Assinale a opção que está de acordo com os postulados da Teoria Ecológica da Criminalidade.',null,'[{"letter":"A","text":"A preservação do meio ambiente deve ser desenvolvida com ênfase em políticas criminais preventivas."},{"letter":"B","text":"A aprendizagem do comportamento criminal inclui técnicas e ocorre, na interação com o outro, pela comunicação com participação ativa."},{"letter":"C","text":"A desorganização social dos grandes centros urbanos pode produzir efeitos criminógenos."},{"letter":"D","text":"A tolerância zero no combate aos crimes ambientais contribui para a garantia da Segurança Pública."},{"letter":"E","text":"O crime não é uma qualidade intrínseca da conduta; é uma conduta qualificada como criminosa pelo controle social."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q071','pmce-2021',71,'criminologia','O conceito de crime como fato social é formulado pelo sociólogo',null,'[{"letter":"A","text":"Karl Marx."},{"letter":"B","text":"Max Weber."},{"letter":"C","text":"Zygmunt Bauman."},{"letter":"D","text":"Howard Becker."},{"letter":"E","text":"Émile Durkheim."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q072','pmce-2021',72,'criminologia','O conceito de controle social informal compreende as seguintes instituições:',null,'[{"letter":"A","text":"Instituições penitenciárias, instituições policiais e varas criminais."},{"letter":"B","text":"Família, Igreja e organizações não governamentais."},{"letter":"C","text":"Poder Legislativo, Poder Executivo e Poder Judiciário."},{"letter":"D","text":"Sociedade civil, mídia e instituições policiais."},{"letter":"E","text":"Manicômios, prisões e conventos."}]'::jsonb,'B','oficial-definitivo','{}'),
('pmce-2021-q073','pmce-2021',73,'criminologia','Assinale a opção que apresenta a tipologia de delinquência estabelecida pela Criminologia Positivista, de Cesare Lombroso.',null,'[{"letter":"A","text":"Criminosos natos, ocasionais, loucos e passionais."},{"letter":"B","text":"Criminosos involuntários, natos, ocasionais, habituais, loucos e passionais."},{"letter":"C","text":"Criminoso cínicos, assassinos violentos ou enérgicos, ladrões ou neurastênicos."},{"letter":"D","text":"Criminosos recuperáveis e irrecuperáveis."},{"letter":"E","text":"Criminalidade de sangue e criminalidade de colarinho branco."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q074','pmce-2021',74,'criminologia','De acordo com a Convenção de Palermo, o conceito de crime organizado pressupõe um(a)',null,'[{"letter":"A","text":"grupo estruturado, de três ou mais pessoas, existente há algum tempo e atuando concertadamente com o propósito de cometer uma ou mais infrações graves."},{"letter":"B","text":"associação de três ou mais pessoas, para o fim específico de cometer crimes."},{"letter":"C","text":"organização paramilitar, milícia particular, grupo ou esquadrão com a finalidade de praticar qualquer dos crimes previstos no Código Penal."},{"letter":"D","text":"grupo composto para a prática de crimes motivados por razões de xenofobia, discriminação ou preconceito de raça, cor, etnia e religião."},{"letter":"E","text":"associação de três ou mais pessoas, para a submissão de alguém, sob sua guarda, poder ou autoridade, com emprego de violência ou grave ameaça, a intenso sofrimento físico ou mental, como forma de aplicar castigo pessoal ou medida de caráter preventivo."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q075','pmce-2021',75,'seguranca-publica','Em relação ao papel das instituições policiais no combate às distintas formas de discriminação, assinale a afirmativa incorreta.',null,'[{"letter":"A","text":"Apesar de não possuir fundamento na Constituição Federal de 1988, o combate ao preconceito no Estado Democrático de Direito é medida recomendada aos órgãos de Segurança Pública."},{"letter":"B","text":"A recusa ou o impedimento de acessar um estabelecimento público ou comercial por discriminação ou preconceito de cor, religião ou procedência nacional, constitui crime."},{"letter":"C","text":"O Supremo Tribunal Federal, em 2019, proferiu decisão equiparando a homofobia ao crime de racismo."},{"letter":"D","text":"As medidas protetivas de urgência previstas na Lei nº 11.340/06 (Lei Maria da Penha) não se aplicam ao homem vítima de violência."},{"letter":"E","text":"A Segurança Pública, como dever do Estado e direito fundamental dos cidadãos, não pode comportar quaisquer formas de discriminação."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q076','pmce-2021',76,'seguranca-publica','Acerca do Programa Nacional de Segurança Pública com Cidadania (PRONASCI), assinale a afirmativa correta.',null,'[{"letter":"A","text":"Pretende erradicar operações conjuntas entre as polícias civis e militares."},{"letter":"B","text":"Pretende alterações legislativas para criação de novos delitos e aumento das penas."},{"letter":"C","text":"Pretende fomentar o comércio de armas de fogo."},{"letter":"D","text":"Pretende articular ações de segurança pública com políticas sociais."},{"letter":"E","text":"Pretende garantir privilégios aos agentes públicos dos órgãos de segurança."}]'::jsonb,'D','oficial-definitivo','{}'),
('pmce-2021-q077','pmce-2021',77,'seguranca-publica','Acerca da participação popular na Segurança Pública, assinale a afirmativa incorreta.',null,'[{"letter":"A","text":"Tem fundamento na Constituição Federal de 1988, que estabelece, em seu Art. 144, a Segurança Pública como dever do Estado, direito e responsabilidade de todos."},{"letter":"B","text":"As conferências estaduais e nacionais de Segurança Pública preconizam a construção de espaços de negociação, busca de consensos, democratização e corresponsabilidade entre o Estado e a sociedade civil."},{"letter":"C","text":"Possibilita a implementação de políticas de Segurança Pública dotadas de maior eficácia e caráter preventivo."},{"letter":"D","text":"Preconiza o incremento da credibilidade e confiança dos órgãos de Segurança Pública perante a sociedade civil."},{"letter":"E","text":"Tem ênfase na busca de planos de Segurança Pública democratizantes, orientados para maior efetividade a partir da confissão espontânea de autores de delitos."}]'::jsonb,'E','oficial-definitivo','{}'),
('pmce-2021-q078','pmce-2021',78,'seguranca-publica','David Bayley e Jerome Skolnick, os primeiros estudiosos sobre policiamento comunitário nos Estados Unidos, indicam quatro principais características desse tipo de policiamento. Nesse sentido, avalie os itens a seguir. 1. Construção de unidades policiais em áreas de conflito conflagrado. 2. Descentralização do comando por área 3. Emprego de civis na polícia e no trabalho de policiamento. 4. Ênfase no policiamento de confronto bélico 5. Estabelecer um plano de segurança pública prévio e, posteriormente, divulgá-lo para a comunidade 6. Relação de reciprocidade entre a polícia e a população 7. Relação verticalizada entre a polícia e a população 8. Reorientação da patrulha de modo a engajar a comunidade na prevenção do crime Assinale a opção que indica somente as características do policiamento comunitário.',null,'[{"letter":"A","text":"1, 2, 3 e 7."},{"letter":"B","text":"1, 2, 5 e 6."},{"letter":"C","text":"2, 3, 6 e 8."},{"letter":"D","text":"3, 4, 6 e 7."},{"letter":"E","text":"4, 6, 7 e 8."}]'::jsonb,'C','oficial-definitivo','{}'),
('pmce-2021-q079','pmce-2021',79,'seguranca-publica','De acordo com o texto da Constituição Federal de 1988, assinale a opção que indica apenas órgãos de Segurança Pública.',null,'[{"letter":"A","text":"Corpos de Bombeiros Militares; Polícia Rodoviária Federal; Polícia Ferroviária Federal e Polícias Penais."},{"letter":"B","text":"Polícia Federal; Polícias Militares; Polícias Civis e Guardas Municipais."},{"letter":"C","text":"Polícia Federal; Polícias Penais; Polícias Civis e Guardas Municipais."},{"letter":"D","text":"Corpos De Bombeiros Militares; Polícias Militares; Forças Armadas e Polícias Civis."},{"letter":"E","text":"Polícias Militares; Polícia Federal; Força Nacional De Segurança Pública e Polícias Civis."}]'::jsonb,'A','oficial-definitivo','{}'),
('pmce-2021-q080','pmce-2021',80,'seguranca-publica','No combate à ação de milícias privadas, devem ser observados alguns critérios de identificação por parte dos órgãos de Segurança Pública. Alguns desses critérios estão listados à seguir, à exceção de um. Assinale-o.',null,'[{"letter":"A","text":"Domínio territorial, ânimo de lucro e participação ativa e reconhecida de agentes do Estado."},{"letter":"B","text":"Organização paramilitar, milícia particular, grupo ou esquadrão."},{"letter":"C","text":"Controle territorial coativo e discurso de legitimação referido à proteção dos moradores e à instauração de uma ordem."},{"letter":"D","text":"Controle de um território e da população que nele habita por parte de um grupo armado irregular."},{"letter":"E","text":"Cooperação da sociedade civil armada com os órgãos de segurança pública. Realização"}]'::jsonb,'E','oficial-definitivo','{}')
